"""Combine independent static artifact audits without changing any release input."""
from pathlib import Path
import argparse,datetime,hashlib,json,re
ap=argparse.ArgumentParser();ap.add_argument('--artifact-dir',required=True,type=Path);ap.add_argument('--output-dir',required=True,type=Path);a=ap.parse_args();art=a.artifact_dir.resolve();o=a.output_dir.resolve()
def load(n):return json.loads((o/n).read_text())
def stamp(p):return {'file':str(p.relative_to(art)),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
def test_counts(p):
 t=p.read_text();return {k:int(re.findall(r'(?m)^.*?\b'+k+r' (\d+)\s*$',t)[-1]) for k in ['tests','pass','fail','cancelled','skipped']}
source_name='installed-artifacts-audit-both.json' if (o/'installed-artifacts-audit-both.json').is_file() else 'installed-artifacts-audit-online.json'
parts={n:load(n) for n in ['asar-audit.json','pe-security.json','documentation-audit.json','toolchain-provenance.json','frozen-inputs-audit.json',source_name,'online-exact-artifact-audit.json']}
offline=(o/'offline-exact-artifact-audit.json').is_file()
if offline:parts['offline-exact-artifact-audit.json']=load('offline-exact-artifact-audit.json')
path_tests=test_counts(o/'directory-and-safety-tests.tap');assert path_tests['tests']==path_tests['pass'] and not any(path_tests[k] for k in ['fail','cancelled','skipped'])
failed=[n for n,p in parts.items() if p['status'] not in ['pass','pending_offline']]
status='fail' if failed else 'pass' if offline and parts['pe-security.json']['status']=='pass' else 'pending_offline'
asar=parts['asar-audit.json'];pe=parts['pe-security.json'];source=parts[source_name];installers=[]
for name in ['online-exact-artifact-audit.json','offline-exact-artifact-audit.json']:
 if name not in parts:continue
 p=parts[name];actual=stamp(art/p['file']);assert actual['bytes']==p['bytes'] and actual['sha256']==p['sha256']
 installers.append({'mode':p['mode'],'status':p['status'],**actual,'productPayloadFiles':p['productFileCount'],'appAsarSha256':p['appAsarSha256'],'uninstaller':'unsigned x86 GUI, asInvoker','installedReadme':p['installedReadme']})
report={'release':'0.2.8','status':status,'generatedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'Independent read-only static PE, compiled NSIS header, exact extraction, hashes, source parity, documentation, compiler provenance, immutable inputs and directory safety audit. No Windows binaries executed.','sourceCheckpoint':json.loads((art/'source-checkpoint.json').read_text()),'installers':installers,'checks':{'allAvailableSetupFixedAndStringVersions028':pe['checks']['allPresentInstallersVersion028'] and pe['checks']['allInstallerStringVersions028'],'allAvailableSetupAsInvoker':pe['checks']['allPresentInstallersAsInvoker'],'allCheckedPECertificateDirectoriesEmpty':pe['checks']['allCertificateDirectoriesEmpty'],'payloadManifestExact':all(p['exactProductAndAuxiliaryInventory'] for n,p in parts.items() if n.endswith('-exact-artifact-audit.json')),'asarSourceAndDependencyParity':asar['status']=='pass','pinnedElectron45RuntimeAndLauncher':pe['checks']['payloadLauncherExactPinnedRuntime'],'all72OfflineRuntimeFilesExactOfficialArchive':pe['checks']['all72RuntimePayloadFilesExactPinnedArchive'],'onlineDownloadCancelHashStageOrder':all(source['sourceGuards'].values()),'installedReadmeCurrentAndAccurate':parts['documentation-audit.json']['status']=='pass','directory011RegressionAndSafetyChecks':path_tests['tests']==path_tests['pass'],'frozen941InputsUnchanged':parts['frozen-inputs-audit.json']['status']=='pass','officialCachedCompilerFilesMatchPinnedPackages':parts['toolchain-provenance.json']['status']=='pass'},'asar':{'bytes':asar['appAsar']['bytes'],'sha256':asar['appAsar']['sha256'],'packagedFiles':asar['totalFiles'],'sourceAssetFilesExcludingSanitizedManifest':asar['sourceFiles'],'projectVersion':asar['projectVersion'],'unpackedFiles':asar['unpackedFileCount'],'windowsNativeFiles':asar['unpackedNativeFileCount']},'runtime':source['runtime'],'directoryAndSafetyTests':path_tests,'failedReports':failed,'reports':[stamp(o/n) for n in parts],'reproduce':'bash audit/reproduce-audit.sh /path/to/MintPortrait-Source /path/to/release-0.2.8','limitations':['Unsigned development candidate, not Windows install, runtime, native DLL, download/cancel UI or uninstall acceptance.','Static security flags and exact source/payload parity do not prove malware absence or real Windows security behavior.','No Windows execution, private photo access, credential use, network download, user-machine access, installation, upload or publication performed by this auditor.']}
(art/'artifact-audit.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'status':status,'installers':installers,'checks':report['checks'],'directoryAndSafetyTests':path_tests},ensure_ascii=False,indent=2));assert status!='fail'
